// Layout and exported assets from Figma nodes 1667:3099, 1667:3962, 1667:3127.
const root='./assets/onboarding/';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const asset=(node,x,y,cls='')=>`<img class="onb-asset ${cls}" src="${root}1667-${node}.svg" alt="" style="left:${x}px;top:${y}px" data-figma-asset="1667:${node}">`;
const chrome=(title,back,y=72)=>`${asset(3109,0,0)}${asset(title==='认识一下它'?3971:title?3140:3105,144,857)}${title?`<header class="onb-heading" style="top:${y}px"><button class="onb-back" data-go="${back}" aria-label="返回">${asset(3988,0,0)}</button><h1>${title}</h1></header>`:''}`;
const button=(text,node,y,attrs='')=>{const label=node===3104?3111:node===3970?3987:3188;const width=node===3104?144:node===3970?48:64;return `<button class="onb-primary" aria-label="${text}" style="top:${y}px" ${attrs}>${asset(node,0,0)}${asset(label,(353-width)/2,19)}</button>`;};
function input(label,name,type,y,placeholder='',extra=''){
 return `<label class="onb-field" style="top:${y}px"><span>${label}</span><div class="onb-input">${asset(3965,0,0)}<input name="${name}" type="${type}" aria-label="${label}" placeholder="${placeholder}" ${extra}>${type==='date'?asset(3997,311,14):asset(4002,326,20)}</div></label>`;
}
export function login(hasPet=false,demo=false){return `<section class="onb-canvas onb-welcome onb-login" aria-label="欢迎使用 POMEPET">${chrome()}${asset(3110,115,186)}${asset(3108,25,255,'onb-illustration')}<h1 class="onb-tagline">记下它的小日常</h1><p class="onb-subtitle">从今天开始，陪它慢慢长大。</p><button class="onb-primary onb-login-link" style="top:692px" data-go="petform" aria-label="注册">${asset(3104,0,0)}<span>注册</span></button><button class="onb-guest" data-go="${hasPet?'today':'petform'}">${hasPet?'继续使用本机记录':'直接开始记录'}</button><p class="onb-login-note">数据保存在当前设备</p></section>`;}
export function welcome(){return `<section class="onb-canvas onb-welcome" aria-label="欢迎使用 POMEPET">${chrome()}${asset(3110,115,186)}${asset(3108,25,255,'onb-illustration')}<h1 class="onb-tagline">记下它的小日常</h1><p class="onb-subtitle">从今天开始，陪它慢慢长大。</p>${button('创建我的第一只宠物',3104,692,'data-go="petform"')}<p class="onb-noaccount">无需注册，开始记录</p></section>`;}
export function petform(hasPet){return `<section class="onb-canvas onb-pet">${chrome('认识一下它',hasPet?'mine':'welcome',68)}<form id="petForm">${asset(3964,150,136)}<label class="onb-avatar" aria-label="添加宠物头像">${asset(3972,5,17,'onb-illustration')}<img id="avatarPreview" hidden alt="宠物头像"><input type="file" id="avatarInput" accept="image/*"></label><p class="onb-avatar-caption">添加宠物头像</p>${input('Name/名字','name','text',288,'名字','required maxlength="40" autocomplete="off"')}<div class="onb-kinds" role="radiogroup" aria-label="宠物种类">${['猫咪','狗狗','其他'].map((kind,i)=>`<label>${asset(3967,0,0)}<input type="radio" name="kind" value="${kind}" ${i===0?'checked':''}><span>${kind}</span></label>`).join('')}</div>${input('Breed/品种','breed','text',429,'英国长毛猫','maxlength="80"')}<label class="onb-field" style="top:517px"><span>Sex/性别</span><div class="onb-input">${asset(3965,0,0)}<select name="sex" aria-label="Sex/性别"><option value="未知">未知</option><option value="公">公</option><option value="母">母</option></select>${asset(4002,326,20)}</div></label>${input('Birthday/生日','birthday','date',612)}${button('下一步',3970,701,'type="submit"')}</form></section>`;}
const defaultList=['喂食','换水','剪指甲','梳毛','换猫砂','体重','随手日记'];
export function checklist(chosen=[],category='日常护理',custom=[],kind='猫咪'){
 const groups={'日常护理':defaultList.map(x=>x==='换猫砂'&&kind==='狗狗'?'遛狗':x),'健康记录':['体重','驱虫','疫苗','用药'],'生活回忆':['随手日记','照片']};
 const items=[...groups[category],...custom.filter(x=>x.category===category).map(x=>x.name)];
 return `<section class="onb-canvas onb-checklist">${chrome('它的照护清单','petform')}<p class="onb-intro">选一些常用事项，以后可以随时调整</p><div class="onb-categories" role="group" aria-label="照护类别">${Object.keys(groups).map(c=>`<button type="button" data-care-category="${c}" class="${c===category?'selected':''}">${asset(c===category?3129:3130,0,0)}<span>${c}</span></button>`).join('')}</div><form id="checklist"><div class="onb-care-card ${items.length>7?'onb-care-scroll':''}">${asset(3132,0,0)}<div class="onb-care-rows">${items.map((item,i)=>`${i?asset(3133,0,62+58*(i-1)):''}<label class="onb-care-row" style="top:${i<6?29+56*i:373+56*(i-6)}px"><input name="chosen" value="${escape(item)}" type="checkbox" ${chosen.includes(item)?'checked':''}><img class="onb-check-image" src="${root}1667-${chosen.includes(item)?3158:3147}.svg" alt=""><span>${escape(item)}</span></label>`).join('')}</div></div><button id="customCare" class="onb-custom" type="button">＋ 添加自定义事项</button>${button('开始记录',3139,706,'type="submit"')}</form></section>`;
}
export function scaleOnboarding(){const canvas=document.querySelector('.onb-canvas');if(canvas){const factor=window.innerWidth<=600?window.innerWidth/402:1;canvas.style.zoom=factor;document.documentElement.style.setProperty('--ui-scale',factor);}}



